(function execute(inputs, outputs) {
 
var currentRecord = inputs.current_record;



function getMeasurements(currentRecordFields) {
    // Inicializa o payload
    var payload = {
        "Measurements": [],
        "Counters": []  // Inicializando o campo "Counters"
    };

      if (currentRecordFields.variables.abl.getValue() == 'true') {
       // gs.info('Integra Linha 15');
            payload.Measurements.push({
                "MeasType": "ZA03", //Área Bruta Locável
                "MeasValue": inputs.areaTotalLuc.replace(/\./g, "").replace(",", ".") || 'não há', // Valor do tamanho do AC
                "MeasValidFrom": inputs.dataInicio
                // "MeasValidFrom": getMeasValidFrom(
                //     currentRecordFields.variables.inicio_vigencia,
                //     currentRecordFields.variables.change_start_date //depois
                //     //antes data_de_inicio_de_criacao_da_luc
                // ),
               // "MeasValidTo": "2040-12-31"
            });
           // gs.info('Linha Payload Measurements: ' + JSON.stringify(payload.Measurements, null, 2));
            //payload.Counters.push({
              //  "NameCharacteristic": "Não há" // Relacionado ao MeasType "ZD06"
            //});
        }

       /* if (currentRecordFields.variables.do_you_have_crd_novo.getValue() == 'yes' || currentRecordFields.variables.do_you_have_crd_novo.getValue() == 'Yes') {
            payload.Measurements.push({
                "MeasType": "ZD01", //CRD
                "MeasValue": currentRecordFields.variables.crd_value_vs_novo.getDisplayValue() || 'não há', // Valor do tamanho do AC
                "MeasValidFrom": getMeasValidFrom(
                    currentRecordFields.variables.inicio_vigencia,
                    currentRecordFields.variables.data_de_inicio_de_criacao_da_luc
                ),
                //"MeasValidTo": "2040-12-31"
            });
            //payload.Counters.push({
              //  "NameCharacteristic": "Não há" // Relacionado ao MeasType "ZD06"
            //});
        }*/

    // Verifica se measurements está habilitado
   // if (currentRecordFields.variables.measurements.getValue() == 'true') {

         if (currentRecordFields.variables.tr.getValue() == 'true') {

            //var numeroTR = currentRecordFields.variables.tr_value.getDisplayValue();
            //var valorDecimalTR = parseFloat(numeroTR); 

            payload.Measurements.push({
                "MeasType": "ZD06", // Tipo de medição para ar condicionado
                "MeasValue": currentRecordFields.variables.tr_value.getDisplayValue().replace(/\./g, "").replace(",", ".") || 'não há', // Valor do tamanho do AC
                "MeasValidFrom": getMeasValidFrom(
                    currentRecordFields.variables.inicio_vigencia,
                    currentRecordFields.variables.data_de_inicio_de_criacao_da_luc
                ),
               // "MeasValidTo": "2040-12-31"
            });
            //payload.Counters.push({
                //"NameCharacteristic": "Z_MEDIDOR_AR_CONDICIONADO" // Relacionado ao MeasType "ZD06"
            //});
        }
        // 1. Verifica o campo u_agua2
        if (currentRecordFields.variables.u_agua2 == 'Yes') {

            //var numeroAgua = inputs.areaTotalLuc;
            //var valorDecimalAgua = parseFloat(numeroAgua); 

            payload.Measurements.push({
                "MeasType": "ZF02", // Tipo de medição para água
                "MeasValue": inputs.areaTotalLuc.replace(/\./g, "").replace(",", ".") || 'não há', // Valor do medidor de água
                "MeasValidFrom": getMeasValidFrom(
                    currentRecordFields.variables.inicio_vigencia,
                    currentRecordFields.variables.data_de_inicio_de_criacao_da_luc
                ),
               // "MeasValidTo": "2040-12-31"
            });
            // Adiciona o contador para o medidor de água
            payload.Counters.push({
                "NameCharacteristic": "Z_MEDIDOR_AGUA" // Relacionado ao MeasType "ZF02"
            });
        }

        // 2. Verifica o campo u_energia2
        if (currentRecordFields.variables.u_energia2 == 'Yes') {

            //var numeroEnerg = inputs.areaTotalLuc;
            //var valorDecimalEnerg = parseFloat(numeroEnerg); 

            payload.Measurements.push({
                "MeasType": "ZF01", // Tipo de medição para energia
                "MeasValue": inputs.areaTotalLuc.replace(/\./g, "").replace(",", ".") || 'não há', // Valor do medidor de energia
                "MeasValidFrom": getMeasValidFrom(
                    currentRecordFields.variables.inicio_vigencia,
                    currentRecordFields.variables.data_de_inicio_de_criacao_da_luc
                ),
               // "MeasValidTo": "2040-12-31"
            });
            // Adiciona o contador para o medidor de energia
            payload.Counters.push({
                "NameCharacteristic": "Z_MEDIDOR_ENERGIA" // Relacionado ao MeasType "ZF01"
            });
        }

        // 3. Verifica o campo u_gas2
        if (currentRecordFields.variables.u_gas2 == 'Yes') {

            //var numeroGas = inputs.areaTotalLuc;
            //var valorDecimalGas = parseFloat(numeroGas); 

            payload.Measurements.push({
                "MeasType": "ZD01", // Tipo de medição para gás
                "MeasValue": inputs.areaTotalLuc.replace(/\./g, "").replace(",", ".") || 'não há', // Valor do medidor de gás
                "MeasValidFrom": getMeasValidFrom(
                    currentRecordFields.variables.inicio_vigencia,
                    currentRecordFields.variables.data_de_inicio_de_criacao_da_luc
                ),
                //"MeasValidTo": "2040-12-31"
            });
            // Adiciona o contador para o medidor de gás
            payload.Counters.push({
                "NameCharacteristic": "Z_MEDIDOR_GAS" // Relacionado ao MeasType "ZD01"
            });
        }
    //} else {
        // Caso measurements não esteja habilitado
       // payload = {"Measurements": [], "Counters": []};
   // }

   // gs.info('Linha Payload Measurements: ' + JSON.stringify(payload));
    return payload; // Retorna o objeto final
}

// Função auxiliar para calcular o campo MeasValidFrom
function getMeasValidFrom(inicioVigencia, dataInicioCriacaoLuc) {
    // Função auxiliar para formatar a data
    function formatDate(date) {
        var day = date.getDate();
        var month = date.getMonth() + 1; // Janeiro é 0!
        var year = date.getFullYear();

        // Adiciona o zero à esquerda se o dia ou mês for menor que 10
        return year + '-' + (month < 10 ? '0' + month : month) + '-' + (day < 10 ? '0' + day : day);
    }

    // Verifica se inicioVigencia é válido
    if (inicioVigencia) {
        return formatDate(new Date(inicioVigencia));
    } else if (dataInicioCriacaoLuc) {
        return formatDate(new Date(dataInicioCriacaoLuc));
    } else {
        return 'não há';
    }
}

// Chama a função e obtém o payload
var payload;
if (currentRecord.variables.measurements.getValue() == 'true' || currentRecord.variables.crd.getValue() == 'true' || currentRecord.variables.abl.getValue() == 'true' || currentRecord.variables.reserva_tecnica.getValue() == 'true' || currentRecord.variables.tr.getValue() == 'true') {
    payload = getMeasurements(currentRecord);
    gs.info("Payload Gerado IF: " + JSON.stringify(payload)); // Apenas para debug
} else {
    payload = {"Measurements": [], "Counters": []};
    gs.info("Payload Gerado ELSE: " + JSON.stringify(payload)); // Apenas para debug
}

var measurements = getMeasurements(currentRecord);

// Aqui você pode usar o payload gerado para formar o seu objeto final
var catLoja = inputs.current_record.variables.luc_category.getValue();
var catLojaResult = '';

if (catLoja == 'store') {
    catLojaResult = '1001';
} else if (catLoja == 'mall') {
    catLojaResult = '1003';
} else if (catLoja == 'room') {
    catLojaResult = '1008';
} else {
    catLojaResult = 'Não há';
}

var salesRentable = inputs.salesRentableMRVS;
var propriedadeManual = inputs.propriedadeMRVS;
var salesResult = '';



if(salesRentable == 'own' || salesRentable == 'PRÓPRIA' || propriedadeManual == 'own'){
    salesResult = 'LOCA';
}else if(salesRentable == 'third'  || salesRentable == 'VENDIDA' || propriedadeManual == 'third' ){
    salesResult = 'VEND';
}else{
    salesResult = 'Não encontrado';
}

//if(!salesRentable){
  //  salesResult = inputs.propriedadeMRVS;
//}

var partBuilding = inputs.parteEdificioMRVS;
var mapping = {
    'area_padrao': '01',
    'taste_lab': '02',
    'praca': '03',
    'alameda': '04',
    'estacionamento': '05',
    'restaurante': '06'
};

var partBuildingResult = mapping[partBuilding] || 'Não há';


// Obtém a data original no formato "dd/mm/yyyy"
var originalDate = inputs.current_record.variables.change_start_date.getDisplayValue();

// Separa a data nas partes de dia, mês e ano
var dateParts = originalDate.split("/");  // Isso irá criar um array [dia, mês, ano]

// Cria um objeto Date no formato "yyyy-mm-dd"
var formattedDate = new Date(dateParts[2], dateParts[1] - 1, dateParts[0]); // Mês começa do 0 (0 = Janeiro)

// Função para formatar a data no formato "yyyy-mm-dd"
function formatDate(date) {
    var year = date.getFullYear();
    var month = (date.getMonth() + 1).toString().padStart(2, '0'); // Adiciona o zero à esquerda se necessário
    var day = date.getDate().toString().padStart(2, '0'); // Adiciona o zero à esquerda se necessário

    return year + '-' + month + '-' + day;
}

// Aplica a formatação
var finalDate = formatDate(formattedDate);

var clasManual = inputs.classificacaoManual;
var clasExtra =  inputs.classificacaoPropriedadeExtra;

var categorizacaoFinal = '';
if(inputs.categorizacaoEspaco == 'SATELITE' || clasManual == 'Satélite' || clasExtra == 'Satélite'){
    categorizacaoFinal = 'SATÉLITE';
}else if(inputs.categorizacaoEspaco == 'MEGA-LOJA' || clasManual == 'Mega loja' || clasExtra == 'Mega loja'){
    categorizacaoFinal = 'MEGA LOJA'
} else if(inputs.categorizacaoEspaco == 'SEMI-ANCORA' || clasManual == 'Semi âncora' || clasExtra == 'Semi âncora' || clasExtra == 'Semi Âncora'){
    categorizacaoFinal = 'SEMI ÂNCORA'
} else if(inputs.categorizacaoEspaco == 'ANCORA' || clasManual == 'Âncora' || clasExtra == 'Âncora'){
    categorizacaoFinal = 'ÂNCORA'
} else {
    categorizacaoFinal = inputs.categorizacaoEspaco;
}

function formatDateToYYYYMMDD(dateString) {
    var parts = dateString.split('/');
    var day = parts[0];
    var month = parts[1];
    var year = parts[2];

    return year + '-' + month + '-' + day;
}

var myObj = {
    "CompanyCode": inputs.current_record.variables.company_code.getDisplayValue(), // FORM.company_code
    "BusinessEntity": inputs.current_record.variables.shopping.u_unit_code.getDisplayValue(), // form.company.name
    "Luc": inputs.novaLuc, // form.codigo da nova luc
    "LucType": "RU", // fixo
    "UsageType": catLojaResult, // form.categoria da LUC
    "LucText": inputs.novaLuc, // Concatena o código com texto
    "Building": '1', // form.parte_do_edificio
    "ExistingULNo": inputs.novaLuc, // Verificar: repetir para cadastro
    "ClassTypeOfUse": categorizacaoFinal.toUpperCase().toString(), // form.categorizacao_do_espaco
   // "ValidFrom": finalDate, // form.data_de_inicio_de_criacao_da_luc
    //"ValidTo": "2040-01-01", // Exemplo preenchido
    //"FirstPostingFrom": finalDate, // form.data_de_inicio_de_criacao_da_luc
    "CPICompanyType": "CPI1", // Verificar com a equipe
    "CPIBudgetType": "CG", // Verificar com a equipe
    "AdditionalData": {
        "SaleRentable": salesResult, // Verificar com faturamento
        //"Piso": "", // Verificar com o SAP se é fixo
       // "Floor": inputs.andarFrom, // form.Pavimento / Andar
        //"FloorTo": inputs.andarAte, // form.Pavimento / Andar
        //"LocationFloor": inputs.current_record.variables.corredor_asset.getDisplayValue() // form.corredor_asset
       // "Region":inputs.corredorAssetMRVS,
        //"PartBuilding": partBuildingResult
    },
    "Measurements": payload.Measurements, // Adiciona as medições ao objeto principal
    "Counters": payload.Counters // Inclui os contadores no objeto final
};
   
    outputs.payloadbasic = myObj;
 
})(inputs, outputs);

